import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

/**
 * The `inflow_model` allows you to model a test account that receives regular income or makes
 * regular payments on a loan. Any transactions generated by the `inflow_model` will appear in
 * addition to randomly generated test data or transactions specified by `override_accounts`.
 */
export type InflowModel = {
  /**
   * Inflow model. One of the following:
   *
   * `none`: No income
   *
   * `monthly-income`: Income occurs once per month `monthly-balance-payment`: Pays off the balance
   * on a liability account at the given statement day of month.
   *
   * `monthly-interest-only-payment`: Makes an interest-only payment on a liability account at the
   * given statement day of month.
   *
   * Note that account types supported by Liabilities will accrue interest in the Sandbox. The types
   * impacted are account type `credit` with subtype `credit` or `paypal`, and account type `loan`
   * with subtype `student` or `mortgage`.
   */
  type: string;
  /** Amount of income per month. This value is required if `type` is `monthly-income`. */
  incomeAmount: number;
  /**
   * Number between 1 and 28, or `last` meaning the last day of the month. The day of the month on
   * which the income transaction will appear. This field is required if `type` is `monthly-income`,
   * `monthly-balance-payment` or `monthly-interest-only-payment`.
   */
  paymentDayOfMonth: number;
  /**
   * The name of the income transaction. This field is required if `type` is `monthly-income`,
   * `monthly-balance-payment` or `monthly-interest-only-payment`.
   */
  transactionName: string;
  /**
   * Number between 1 and 28, or `last` meaning the last day of the month. The day of the month on
   * which the balance is calculated for the next payment. This field is required if `type` is
   * `monthly-balance-payment` or `monthly-interest-only-payment`.
   */
  statementDayOfMonth: string;
};

export const inflowModelSchema: Schema<InflowModel> = s.object<InflowModel>({
  type: s.string(),
  incomeAmount: s.float64(),
  paymentDayOfMonth: s.float64(),
  transactionName: s.string(),
  statementDayOfMonth: s.string(),
  _keysMap: {
    incomeAmount: "income_amount",
    paymentDayOfMonth: "payment_day_of_month",
    transactionName: "transaction_name",
    statementDayOfMonth: "statement_day_of_month",
  },
});
